const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/document_management/fields/%7Bfield_id_or_name%7D/values',
  qs: {
    include_inactive: 'SOME_BOOLEAN_VALUE',
    document_collection_id: 'SOME_STRING_VALUE',
    upload_collection_id: 'SOME_STRING_VALUE',
    keyword: 'SOME_STRING_VALUE',
    sort_by: 'SOME_STRING_VALUE',
    sort_order: 'SOME_STRING_VALUE',
    include_all: 'SOME_BOOLEAN_VALUE',
    include_readonly: 'SOME_BOOLEAN_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    locale: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/document_management/fields/%7Bfield_id_or_name%7D/values?include_inactive=SOME_BOOLEAN_VALUE&document_collection_id=SOME_STRING_VALUE&upload_collection_id=SOME_STRING_VALUE&keyword=SOME_STRING_VALUE&sort_by=SOME_STRING_VALUE&sort_order=SOME_STRING_VALUE&include_all=SOME_BOOLEAN_VALUE&include_readonly=SOME_BOOLEAN_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&locale=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
